  1→package jlsm.table.internal;
  2→
  3→import java.nio.charset.StandardCharsets;
  4→import java.util.List;
  5→
  6→import jlsm.table.EncryptionSpec;
  7→import jlsm.table.FieldDefinition;
  8→import jlsm.table.JlsmSchema;
  9→
 10→/**
 11→ * Dispatch table mapping field positions to their encryption/decryption functions. Constructed once
 12→ * at serializer creation time; immutable and thread-safe after construction.
 13→ *
 14→ * <p>
 15→ * For each field in the schema, checks its {@link EncryptionSpec} and builds the appropriate
 16→ * encryptor/decryptor pair. If the key holder is {@code null}, all entries are {@code null} (no
 17→ * encryption).
 18→ *
 19→ * <p>
 20→ * Governed by: .decisions/field-encryption-api-design/adr.md
 21→ */
 22→public final class FieldEncryptionDispatch {
 23→
 24→    private final FieldEncryptor[] encryptors;
 25→    private final FieldDecryptor[] decryptors;
 26→
 27→    /**
 28→     * Encrypts a byte array field value.
 29→     */
 30→    @FunctionalInterface
 31→    public interface FieldEncryptor {
 32→        byte[] encrypt(byte[] plaintext);
 33→    }
 34→
 35→    /**
 36→     * Decrypts a byte array field value.
 37→     */
 38→    @FunctionalInterface
 39→    public interface FieldDecryptor {
 40→        byte[] decrypt(byte[] ciphertext);
 41→    }
 42→
 43→    /**
 44→     * Constructs a dispatch table for the given schema and key holder.
 45→     *
 46→     * @param schema the schema describing the document structure; must not be null
 47→     * @param keyHolder the key holder providing encryption keys; may be null (no encryption)
 48→     */
 49→    public FieldEncryptionDispatch(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
 50→        assert schema != null : "schema must not be null";
 51→
 52→        final List<FieldDefinition> fields = schema.fields();
 53→        final int fieldCount = fields.size();
 54→        this.encryptors = new FieldEncryptor[fieldCount];
 55→        this.decryptors = new FieldDecryptor[fieldCount];
 56→
 57→        if (keyHolder == null) {
 58→            // No encryption — all entries remain null
 59→            return;
 60→        }
 61→
 62→        for (int i = 0; i < fieldCount; i++) {
 63→            final FieldDefinition fd = fields.get(i);
 64→            final EncryptionSpec spec = fd.encryption();
 65→
 66→            switch (spec) {
 67→                case EncryptionSpec.None _ -> {
 68→                    // No encryption for this field
 69→                }
 70→                case EncryptionSpec.Deterministic _ -> {
 71→                    final AesSivEncryptor siv = new AesSivEncryptor(keyHolder);
 72→                    final byte[] associatedData =
 73→                            fd.name().getBytes(StandardCharsets.UTF_8);
 74→                    encryptors[i] = plaintext -> siv.encrypt(plaintext, associatedData);
 75→                    decryptors[i] = ciphertext -> siv.decrypt(ciphertext, associatedData);
 76→                }
 77→                case EncryptionSpec.OrderPreserving _ -> {
 78→                    // OrderPreserving requires domain/range configuration.
 79→                    // For generic byte-level dispatch, use long-based OPE.
 80→                    final BoldyrevaOpeEncryptor ope = new BoldyrevaOpeEncryptor(keyHolder,
 81→                            Long.MAX_VALUE / 2, Long.MAX_VALUE);
 82→                    encryptors[i] = plaintext -> opeEncryptBytes(ope, plaintext);
 83→                    decryptors[i] = ciphertext -> opeDecryptBytes(ope, ciphertext);
 84→                }
 85→                case EncryptionSpec.DistancePreserving _ -> {
 86→                    // DistancePreserving operates on float[] vectors, not byte[].
 87→                    // Handled separately in the serializer. Leave null for byte dispatch.
 88→                }
 89→                case EncryptionSpec.Opaque _ -> {
 90→                    final AesGcmEncryptor gcm = new AesGcmEncryptor(keyHolder);
 91→                    encryptors[i] = gcm::encrypt;
 92→                    decryptors[i] = gcm::decrypt;
 93→                }
 94→            }
 95→        }
 96→    }
 97→
 98→    /**
 99→     * Returns the encryptor for the field at the given index, or {@code null} if no encryption is
100→     * configured.
101→     *
102→     * @param fieldIndex the zero-based field index
103→     * @return the encryptor, or null
104→     */
105→    public FieldEncryptor encryptorFor(int fieldIndex) {
106→        assert fieldIndex >= 0 && fieldIndex < encryptors.length
107→                : "fieldIndex out of bounds: " + fieldIndex;
108→        return encryptors[fieldIndex];
109→    }
110→
111→    /**
112→     * Returns the decryptor for the field at the given index, or {@code null} if no encryption is
113→     * configured.
114→     *
115→     * @param fieldIndex the zero-based field index
116→     * @return the decryptor, or null
117→     */
118→    public FieldDecryptor decryptorFor(int fieldIndex) {
119→        assert fieldIndex >= 0 && fieldIndex < decryptors.length
120→                : "fieldIndex out of bounds: " + fieldIndex;
121→        return decryptors[fieldIndex];
122→    }
123→
124→    // -- OPE byte helpers -------------------------------------------------
125→
126→    /**
127→     * Encodes a byte[] as a positive long, encrypts with OPE, returns the encrypted long as bytes.
128→     */
129→    private static byte[] opeEncryptBytes(BoldyrevaOpeEncryptor ope, byte[] plaintext) {
130→        final long value = bytesToPositiveLong(plaintext);
131→        final long encrypted = ope.encrypt(value);
132→        return longToBytes(encrypted);
133→    }
134→
135→    /**
136→     * Decrypts OPE ciphertext bytes back to the original byte[] representation.
137→     */
138→    private static byte[] opeDecryptBytes(BoldyrevaOpeEncryptor ope, byte[] ciphertext) {
139→        final long encValue = bytesTo8ByteLong(ciphertext);
140→        final long decrypted = ope.decrypt(encValue);
141→        return positiveLongToBytes(decrypted);
142→    }
143→
144→    /**
145→     * Converts up to 6 bytes of data into a positive long in [1..Long.MAX_VALUE/2]. Format: first
146→     * byte = original length, followed by up to 6 data bytes packed into a long.
147→     */
148→    private static long bytesToPositiveLong(byte[] data) {
149→        assert data != null : "data must not be null";
150→        if (data.length > 6) {
151→            throw new IllegalArgumentException(
152→                    "OPE byte encryption supports at most 6 bytes of data, got " + data.length);
153→        }
154→        long result = 1; // ensure positive, minimum = 1
155→        result += ((long) data.length) << 48;
156→        for (int i = 0; i < data.length; i++) {
157→            result += ((long) (data[i] & 0xFF)) << (40 - i * 8);
158→        }
159→        return result;
160→    }
161→
162→    private static byte[] positiveLongToBytes(long value) {
163→        value -= 1; // undo the +1 offset
164→        final int len = (int) ((value >>> 48) & 0xFF);
165→        final byte[] result = new byte[len];
166→        for (int i = 0; i < len; i++) {
167→            result[i] = (byte) ((value >>> (40 - i * 8)) & 0xFF);
168→        }
169→        return result;
170→    }
171→
172→    private static byte[] longToBytes(long value) {
173→        final byte[] buf = new byte[8];
174→        for (int i = 0; i < 8; i++) {
175→            buf[i] = (byte) (value >>> (56 - i * 8));
176→        }
177→        return buf;
178→    }
179→
180→    private static long bytesTo8ByteLong(byte[] buf) {
181→        assert buf.length == 8 : "expected 8 bytes for long";
182→        long result = 0;
183→        for (int i = 0; i < 8; i++) {
184→            result |= ((long) (buf[i] & 0xFF)) << (56 - i * 8);
185→        }
186→        return result;
187→    }
188→}
