  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jlsm.table.internal.EncryptionKeyHolder;
  5→import jlsm.table.internal.FieldEncryptionDispatch;
  6→import jdk.incubator.vector.ByteVector;
  7→import jdk.incubator.vector.DoubleVector;
  8→import jdk.incubator.vector.FloatVector;
  9→import jdk.incubator.vector.IntVector;
 10→import jdk.incubator.vector.LongVector;
 11→import jdk.incubator.vector.VectorShuffle;
 12→import jdk.incubator.vector.VectorSpecies;
 13→
 14→import java.lang.foreign.MemorySegment;
 15→import java.lang.foreign.ValueLayout;
 16→import java.nio.charset.StandardCharsets;
 17→import java.util.List;
 18→import java.util.Objects;
 19→import java.util.Optional;
 20→
 21→/**
 22→ * Binary serializer for {@link JlsmDocument} values.
 23→ *
 24→ * <p>
 25→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 26→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 27→ *
 28→ * <p>
 29→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 30→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 31→ * {@code null}.
 32→ *
 33→ * <p>
 34→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 35→ * {@code jdk.incubator.vector}.
 36→ */
 37→public final class DocumentSerializer {
 38→
 39→    private DocumentSerializer() {
 40→    }
 41→
 42→    /**
 43→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 44→     * schema.
 45→     *
 46→     * @param schema the schema describing the document structure; must not be null
 47→     * @return a MemorySerializer for JlsmDocument
 48→     */
 49→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 50→        Objects.requireNonNull(schema, "schema must not be null");
 51→        return new SchemaSerializer(schema, null);
 52→    }
 53→
 54→    /**
 55→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 56→     * schema, with optional field-level encryption.
 57→     *
 58→     * @param schema the schema describing the document structure; must not be null
 59→     * @param keyHolder the key holder for encryption; may be null (no encryption)
 60→     * @return a MemorySerializer for JlsmDocument
 61→     */
 62→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema,
 63→            EncryptionKeyHolder keyHolder) {
 64→        Objects.requireNonNull(schema, "schema must not be null");
 65→        return new SchemaSerializer(schema, keyHolder);
 66→    }
 67→
 68→    // =========================================================================
 69→    // Implementation
 70→    // =========================================================================
 71→
 72→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 73→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 74→
 75→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 76→    private static final VectorShuffle<Byte> BSWAP32;
 77→
 78→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 79→    private static final VectorShuffle<Byte> BSWAP64;
 80→
 81→    static {
 82→        final int byteLen = BYTE_SPECIES.length();
 83→        final int[] idx32 = new int[byteLen];
 84→        final int[] idx64 = new int[byteLen];
 85→        for (int i = 0; i + 3 < byteLen; i += 4) {
 86→            idx32[i + 0] = i + 3;
 87→            idx32[i + 1] = i + 2;
 88→            idx32[i + 2] = i + 1;
 89→            idx32[i + 3] = i + 0;
 90→        }
 91→        for (int i = 0; i + 7 < byteLen; i += 8) {
 92→            idx64[i + 0] = i + 7;
 93→            idx64[i + 1] = i + 6;
 94→            idx64[i + 2] = i + 5;
 95→            idx64[i + 3] = i + 4;
 96→            idx64[i + 4] = i + 3;
 97→            idx64[i + 5] = i + 2;
 98→            idx64[i + 6] = i + 1;
 99→            idx64[i + 7] = i + 0;
100→        }
101→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
102→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
103→    }
104→
105→    // -------------------------------------------------------------------------
106→    // Serializer implementation
107→    // -------------------------------------------------------------------------
108→
109→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
110→    @FunctionalInterface
111→    private interface FieldDecoder {
112→        Object decode(byte[] buf, Cursor cursor);
113→    }
114→
115→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
116→
117→        private final JlsmSchema schema;
118→        private final boolean[] isBoolField;
119→        private final int[] prefixBoolCount;
120→        private final int fieldCount;
121→        private final int boolCount;
122→        private final int nullMaskBytes;
123→        private final int boolMaskBytes;
124→        private final FieldDecoder[] decoders;
125→
126→        SchemaSerializer(JlsmSchema schema) {
127→            this.schema = schema;
128→
129→            final List<FieldDefinition> fields = schema.fields();
130→            this.fieldCount = fields.size();
131→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
132→
133→            // Precompute boolean field flags and prefix counts
134→            this.isBoolField = new boolean[fieldCount];
135→            this.prefixBoolCount = new int[fieldCount + 1];
136→            int bools = 0;
137→            for (int i = 0; i < fieldCount; i++) {
138→                prefixBoolCount[i] = bools;
139→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
140→                    isBoolField[i] = true;
141→                    bools++;
142→                }
143→            }
144→            prefixBoolCount[fieldCount] = bools;
145→            this.boolCount = bools;
146→
147→            this.nullMaskBytes = (fieldCount + 7) / 8;
148→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
149→
150→            // Build dispatch table for non-boolean field decoders
151→            this.decoders = new FieldDecoder[fieldCount];
152→            for (int i = 0; i < fieldCount; i++) {
153→                if (!isBoolField[i]) {
154→                    final FieldType type = fieldArray[i].type();
155→                    decoders[i] = (buf, cursor) -> decodeField(buf, cursor, type);
156→                }
157→            }
158→        }
159→
160→        @Override
161→        public MemorySegment serialize(JlsmDocument doc) {
162→            Objects.requireNonNull(doc, "doc must not be null");
163→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
164→                    : "document schema mismatch";
165→
166→            final List<FieldDefinition> fields = schema.fields();
167→            final int fieldCount = fields.size();
168→            final Object[] values = doc.values();
169→
170→            // Count boolean fields
171→            final int boolCount = countBoolFields(fields);
172→
173→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
174→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
175→            final int nullMaskBytes = (fieldCount + 7) / 8;
176→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
177→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
178→
179→            // Two-pass: measure then encode
180→            final int payloadSize = measureFields(fields, values);
181→            final int totalSize = headerSize + payloadSize;
182→
183→            final byte[] buf = new byte[totalSize];
184→
185→            // Write header
186→            writeShortBE(buf, 0, (short) schema.version());
187→            writeShortBE(buf, 2, (short) fieldCount);
188→            // Null bitmask
189→            buildNullMask(fields, values, buf, 4);
190→            // Boolean bitmask
191→            if (boolCount > 0) {
192→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
193→            }
194→
195→            // Write values
196→            final Cursor cursor = new Cursor(buf, headerSize);
197→            encodeFields(fields, values, cursor);
198→
199→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
200→            return MemorySegment.ofArray(buf);
201→        }
202→
203→        @Override
204→        public JlsmDocument deserialize(MemorySegment segment) {
205→            Objects.requireNonNull(segment, "segment must not be null");
206→
207→            final ByteArrayView view = extractBytes(segment);
208→            final byte[] buf = view.data();
209→            final Cursor cursor = new Cursor(buf, view.offset());
210→
211→            // Read header
212→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
213→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
214→
215→            // We only read min(writeFieldCount, currentFieldCount) fields
216→            final int readCount = Math.min(writeFieldCount, fieldCount);
217→
218→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
219→            final int writeBoolCount = prefixBoolCount[readCount];
220→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
221→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
222→
223→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
224→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
225→
226→            // Decode values
227→            final Object[] values = new Object[fieldCount];
228→            // Fields beyond readCount remain null (new fields added in a later schema version)
229→
230→            int boolIdx = 0;
231→            for (int i = 0; i < readCount; i++) {
232→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
233→                if (isNull) {
234→                    if (isBoolField[i]) {
235→                        boolIdx++;
236→                    }
237→                    continue;
238→                }
239→                if (isBoolField[i]) {
240→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
241→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
242→                    boolIdx++;
243→                } else {
244→                    values[i] = decoders[i].decode(buf, cursor);
245→                }
246→            }
247→
248→            return new JlsmDocument(schema, values);
249→        }
250→    }
251→
252→    // =========================================================================
253→    // Measure helpers (first pass)
254→    // =========================================================================
255→
256→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
257→        int total = 0;
258→        for (int i = 0; i < fields.size(); i++) {
259→            final FieldDefinition fd = fields.get(i);
260→            final Object val = values[i];
261→            if (val == null) {
262→                continue; // null → no value bytes
263→            }
264→            total += measureField(fd.type(), val);
265→        }
266→        return total;
267→    }
268→
269→    private static int measureField(FieldType type, Object value) {
270→        return switch (type) {
271→            case FieldType.Primitive p -> switch (p) {
272→                case STRING -> {
273→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
274→                    yield varIntSize(utf8.length) + utf8.length;
275→                }
276→                case INT8 -> 1;
277→                case INT16 -> 2;
278→                case INT32 -> 4;
279→                case INT64 -> 8;
280→                case FLOAT16 -> 2;
281→                case FLOAT32 -> 4;
282→                case FLOAT64 -> 8;
283→                case BOOLEAN -> 0; // packed in bitmask
284→                case TIMESTAMP -> 8;
285→            };
286→            case FieldType.ArrayType at -> {
287→                final Object[] arr = (Object[]) value;
288→                int sz = varIntSize(arr.length);
289→                for (Object elem : arr) {
290→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
291→                }
292→                yield sz;
293→            }
294→            case FieldType.VectorType vt -> {
295→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
296→                yield vt.dimensions() * elemBytes;
297→            }
298→            case FieldType.ObjectType ot -> {
299→                final JlsmDocument sub = (JlsmDocument) value;
300→                final List<FieldDefinition> subFields = ot.fields();
301→                final int subBoolCount = countBoolFields(subFields);
302→                final int subNullBytes = (subFields.size() + 7) / 8;
303→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
304→                int sz = subNullBytes + subBoolBytes;
305→                sz += measureFields(subFields, sub.values());
306→                yield sz;
307→            }
308→        };
309→    }
310→
311→    // =========================================================================
312→    // Encode helpers (second pass)
313→    // =========================================================================
314→
315→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
316→        for (int i = 0; i < fields.size(); i++) {
317→            final Object val = values[i];
318→            if (val == null) {
319→                continue;
320→            }
321→            encodeField(c, fields.get(i).type(), val);
322→        }
323→    }
324→
325→    private static void encodeField(Cursor c, FieldType type, Object value) {
326→        switch (type) {
327→            case FieldType.Primitive p -> {
328→                switch (p) {
329→                    case STRING -> {
330→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
331→                        writeVarInt(c, utf8.length);
332→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
333→                        c.pos += utf8.length;
334→                    }
335→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
336→                    case INT16 -> {
337→                        writeShortBE(c.buf, c.pos, (Short) value);
338→                        c.pos += 2;
339→                    }
340→                    case INT32 -> {
341→                        writeIntBE(c.buf, c.pos, (Integer) value);
342→                        c.pos += 4;
343→                    }
344→                    case INT64 -> {
345→                        writeLongBE(c.buf, c.pos, (Long) value);
346→                        c.pos += 8;
347→                    }
348→                    case FLOAT16 -> {
349→                        writeShortBE(c.buf, c.pos, (Short) value);
350→                        c.pos += 2;
351→                    }
352→                    case FLOAT32 -> {
353→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
354→                        c.pos += 4;
355→                    }
356→                    case FLOAT64 -> {
357→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
358→                        c.pos += 8;
359→                    }
360→                    case BOOLEAN -> {
361→                        // Boolean values are packed in the bool bitmask; nothing here
362→                    }
363→                    case TIMESTAMP -> {
364→                        writeLongBE(c.buf, c.pos, (Long) value);
365→                        c.pos += 8;
366→                    }
367→                }
368→            }
369→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
370→            case FieldType.VectorType vt -> encodeVector(c, vt, value);
371→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
372→        }
373→    }
374→
375→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
376→        writeVarInt(c, arr.length);
377→        // SIMD-accelerated paths for contiguous numeric types
378→        if (elemType == FieldType.Primitive.INT32) {
379→            encodeInt32Array(c, arr);
380→        } else if (elemType == FieldType.Primitive.INT64) {
381→            encodeInt64Array(c, arr);
382→        } else if (elemType == FieldType.Primitive.FLOAT32) {
383→            encodeFloat32Array(c, arr);
384→        } else if (elemType == FieldType.Primitive.FLOAT64) {
385→            encodeFloat64Array(c, arr);
386→        } else {
387→            for (Object elem : arr) {
388→                if (elem != null) {
389→                    encodeField(c, elemType, elem);
390→                }
391→            }
392→        }
393→    }
394→
395→    private static void encodeVector(Cursor c, FieldType.VectorType vt, Object value) {
396→        final int d = vt.dimensions();
397→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
398→            final float[] vec = (float[]) value;
399→            assert vec.length == d : "vector length must match dimensions";
400→            for (int i = 0; i < d; i++) {
401→                writeIntBE(c.buf, c.pos, Float.floatToRawIntBits(vec[i]));
402→                c.pos += 4;
403→            }
404→        } else {
405→            // FLOAT16 — stored as short[]
406→            final short[] vec = (short[]) value;
407→            assert vec.length == d : "vector length must match dimensions";
408→            for (int i = 0; i < d; i++) {
409→                writeShortBE(c.buf, c.pos, vec[i]);
410→                c.pos += 2;
411→            }
412→        }
413→    }
414→
415→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
416→        final List<FieldDefinition> subFields = ot.fields();
417→        final Object[] subValues = sub.values();
418→        final int boolCount = countBoolFields(subFields);
419→        final int nullMaskBytes = (subFields.size() + 7) / 8;
420→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
421→
422→        final int nullMaskStart = c.pos;
423→        c.pos += nullMaskBytes;
424→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
425→        if (boolCount > 0) {
426→            c.pos += boolMaskBytes;
427→        }
428→
429→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
430→        if (boolCount > 0) {
431→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
432→        }
433→        encodeFields(subFields, subValues, c);
434→    }
