440→    private static void encodeInt32Array(Cursor c, Object[] arr) {
441→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
442→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
443→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
444→        int i = 0;
445→        if (arr.length >= simdElems && simdLen >= 4) {
446→            final int[] ints = new int[simdElems];
447→            while (i + simdElems <= arr.length) {
448→                for (int j = 0; j < simdElems; j++) {
449→                    ints[j] = (Integer) arr[i + j];
450→                }
451→                // Load as bytes (little-endian native), swap to big-endian
452→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
453→                        .reinterpretAsBytes();
454→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
455→                c.pos += simdLen;
456→                i += simdElems;
457→            }
458→        }
459→        // Scalar remainder
460→        while (i < arr.length) {
461→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
462→            c.pos += 4;
463→        }
464→    }
