470→        if (arr.length >= simdElems && simdLen >= 8) {
471→            final long[] longs = new long[simdElems];
472→            while (i + simdElems <= arr.length) {
473→                for (int j = 0; j < simdElems; j++) {
474→                    longs[j] = (Long) arr[i + j];
475→                }
476→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
477→                        .reinterpretAsBytes();
478→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
479→                c.pos += simdLen;
480→                i += simdElems;
481→            }
482→        }
