539→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
540→        return switch (type) {
541→            case FieldType.Primitive p -> switch (p) {
542→                case STRING -> {
543→                    final int len = readVarInt(buf, cursor);
544→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
545→                    cursor.pos += len;
546→                    yield s;
547→                }
548→                case INT8 -> buf[cursor.pos++];
549→                case INT16 -> {
550→                    final short v = readShortBE(buf, cursor.pos);
551→                    cursor.pos += 2;
552→                    yield v;
553→                }
554→                case INT32 -> {
555→                    final int v = readIntBE(buf, cursor.pos);
556→                    cursor.pos += 4;
557→                    yield v;
558→                }
559→                case INT64 -> {
560→                    final long v = readLongBE(buf, cursor.pos);
561→                    cursor.pos += 8;
562→                    yield v;
563→                }
564→                case FLOAT16 -> {
565→                    final short v = readShortBE(buf, cursor.pos);
566→                    cursor.pos += 2;
567→                    yield v;
568→                }
569→                case FLOAT32 -> {
570→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
571→                    cursor.pos += 4;
572→                    yield v;
573→                }
574→                case FLOAT64 -> {
575→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
576→                    cursor.pos += 8;
577→                    yield v;
578→                }
579→                case BOOLEAN ->
580→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
581→                case TIMESTAMP -> {
582→                    final long v = readLongBE(buf, cursor.pos);
583→                    cursor.pos += 8;
584→                    yield v;
585→                }
586→            };
587→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
588→            case FieldType.VectorType vt -> decodeVector(buf, cursor, vt);
589→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
590→        };
591→    }
592→
593→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
594→        final int count = readVarInt(buf, cursor);
595→        // SIMD-accelerated decode for contiguous numeric types
596→        final FieldType elemType = at.elementType();
597→        if (elemType == FieldType.Primitive.INT32) {
598→            return decodeInt32Array(buf, cursor, count);
599→        } else if (elemType == FieldType.Primitive.INT64) {
600→            return decodeInt64Array(buf, cursor, count);
601→        } else if (elemType == FieldType.Primitive.FLOAT32) {
602→            return decodeFloat32Array(buf, cursor, count);
603→        } else if (elemType == FieldType.Primitive.FLOAT64) {
604→            return decodeFloat64Array(buf, cursor, count);
605→        }
606→        final Object[] arr = new Object[count];
607→        for (int i = 0; i < count; i++) {
608→            arr[i] = decodeField(buf, cursor, elemType);
609→        }
610→        return arr;
611→    }
612→
613→    private static Object decodeVector(byte[] buf, Cursor cursor, FieldType.VectorType vt) {
614→        final int d = vt.dimensions();
615→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
616→            final float[] vec = new float[d];
617→            for (int i = 0; i < d; i++) {
618→                vec[i] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
619→                cursor.pos += 4;
620→            }
621→            return vec;
622→        } else {
623→            // FLOAT16 — return as short[]
624→            final short[] vec = new short[d];
625→            for (int i = 0; i < d; i++) {
626→                vec[i] = readShortBE(buf, cursor.pos);
627→                cursor.pos += 2;
628→            }
629→            return vec;
630→        }
631→    }
632→
633→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
634→        final List<FieldDefinition> subFields = ot.fields();
635→        final int subFieldCount = subFields.size();
636→        final int subBoolCount = countBoolFields(subFields);
637→        final int nullMaskBytes = (subFieldCount + 7) / 8;
638→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
639→
640→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
641→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
642→
643→        final Object[] subValues = new Object[subFieldCount];
644→        int boolIdx = 0;
645→        for (int i = 0; i < subFieldCount; i++) {
646→            final FieldDefinition fd = subFields.get(i);
647→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
648→            if (isNull) {
649→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
650→                    boolIdx++;
651→                }
652→                subValues[i] = null;
653→                continue;
654→            }
655→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
656→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
657→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
658→                boolIdx++;
659→            } else {
660→                subValues[i] = decodeField(buf, cursor, fd.type());
661→            }
662→        }
663→
664→        // Synthesize a schema for the sub-document
665→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
666→        return new JlsmDocument(subSchema, subValues);
667→    }
