673→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
674→        final Object[] result = new Object[count];
675→        final int simdLen = BYTE_SPECIES.length();
676→        final int simdElems = simdLen / 4;
677→        final int[] tmp = new int[simdElems];
678→        int i = 0;
679→        if (count >= simdElems && simdLen >= 4) {
680→            while (i + simdElems <= count) {
681→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
682→                        .reinterpretAsInts().intoArray(tmp, 0);
683→                for (int j = 0; j < simdElems; j++) {
684→                    result[i + j] = tmp[j];
685→                }
686→                cursor.pos += simdLen;
687→                i += simdElems;
688→            }
689→        }
690→        while (i < count) {
691→            result[i++] = readIntBE(buf, cursor.pos);
692→            cursor.pos += 4;
693→        }
694→        return result;
695→    }
