770→    // Bitmask helpers
771→    // =========================================================================
772→
773→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
774→            int offset) {
775→        for (int i = 0; i < fields.size(); i++) {
776→            if (values[i] == null) {
777→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
778→            }
779→        }
780→    }
781→
782→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
783→            int offset) {
784→        int boolIdx = 0;
785→        for (int i = 0; i < fields.size(); i++) {
786→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
787→                final Object val = values[i];
788→                if (val instanceof Boolean b && b) {
789→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
790→                }
791→                boolIdx++;
792→            }
793→        }
794→    }
795→
796→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
797→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
798→    }
799→
800→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
801→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
802→    }
803→
804→    private static int countBoolFields(List<FieldDefinition> fields) {
805→        int count = 0;
806→        for (final FieldDefinition fd : fields) {
807→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
808→                count++;
809→            }
810→        }
811→        return count;
812→    }
