814→    // =========================================================================
815→    // VarInt (LEB128 unsigned)
816→    // =========================================================================
817→
818→    private static int varIntSize(int value) {
819→        assert value >= 0 : "VarInt value must be non-negative";
820→        if (value < 128) {
821→            return 1;
822→        }
823→        if (value < 16384) {
824→            return 2;
825→        }
826→        if (value < 2097152) {
827→            return 3;
828→        }
829→        if (value < 268435456) {
830→            return 4;
831→        }
832→        return 5;
833→    }
834→
835→    private static void writeVarInt(Cursor c, int value) {
836→        assert value >= 0 : "VarInt value must be non-negative";
837→        while (true) {
838→            if ((value & ~0x7F) == 0) {
839→                c.buf[c.pos++] = (byte) value;
840→                return;
841→            }
842→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
843→            value >>>= 7;
844→        }
845→    }
846→
847→    private static int readVarInt(byte[] buf, Cursor cursor) {
848→        int result = 0;
849→        int shift = 0;
850→        while (true) {
851→            final byte b = buf[cursor.pos++];
852→            result |= (b & 0x7F) << shift;
853→            if ((b & 0x80) == 0) {
854→                break;
855→            }
856→            shift += 7;
857→            assert shift <= 35 : "VarInt overflow — corrupt data";
858→        }
859→        return result;
860→    }
