866→    private static void writeShortBE(byte[] buf, int offset, short value) {
867→        buf[offset] = (byte) (value >> 8);
868→        buf[offset + 1] = (byte) value;
869→    }
870→
871→    private static short readShortBE(byte[] buf, int offset) {
872→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
873→    }
874→
875→    private static void writeIntBE(byte[] buf, int offset, int value) {
876→        buf[offset] = (byte) (value >> 24);
877→        buf[offset + 1] = (byte) (value >> 16);
878→        buf[offset + 2] = (byte) (value >> 8);
879→        buf[offset + 3] = (byte) value;
880→    }
881→
882→    private static int readIntBE(byte[] buf, int offset) {
883→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
884→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
885→    }
886→
887→    private static void writeLongBE(byte[] buf, int offset, long value) {
888→        buf[offset] = (byte) (value >> 56);
889→        buf[offset + 1] = (byte) (value >> 48);
890→        buf[offset + 2] = (byte) (value >> 40);
891→        buf[offset + 3] = (byte) (value >> 32);
892→        buf[offset + 4] = (byte) (value >> 24);
893→        buf[offset + 5] = (byte) (value >> 16);
894→        buf[offset + 6] = (byte) (value >> 8);
895→        buf[offset + 7] = (byte) value;
896→    }
897→
898→    private static long readLongBE(byte[] buf, int offset) {
899→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
900→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
901→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
902→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
903→    }
