909→    /** View of a byte array with an offset — enables zero-copy for heap-backed segments. */
910→    private record ByteArrayView(byte[] data, int offset) {
911→    }
912→
913→    /**
914→     * Extracts a byte array view from a {@link MemorySegment}. For heap-backed segments (created
915→     * via {@code MemorySegment.ofArray(byte[])}), returns the backing array directly — zero-copy.
916→     * For off-heap or sliced segments, falls back to {@code toArray()}.
917→     */
918→    private static ByteArrayView extractBytes(MemorySegment segment) {
919→        Optional<Object> heapBase = segment.heapBase();
920→        if (heapBase.isPresent() && heapBase.get() instanceof byte[] data
921→                && segment.byteSize() == data.length) {
922→            // Full array — offset is 0 for MemorySegment.ofArray(byte[])
923→            return new ByteArrayView(data, 0);
924→        } else {
925→            byte[] data = segment.toArray(ValueLayout.JAVA_BYTE);
926→            return new ByteArrayView(data, 0);
927→        }
928→    }
