934→    /** Mutable position cursor for sequential byte-array I/O. */
935→    private static final class Cursor {
936→
937→        final byte[] buf;
938→        int pos;
939→
940→        Cursor(byte[] buf, int pos) {
941→            this.buf = buf;
942→            this.pos = pos;
943→        }
944→
945→        /** Advances position by {@code n} bytes and returns the old position. */
946→        int advance(int n) {
947→            final int old = pos;
948→            pos += n;
949→            return old;
950→        }
951→    }
