  3→/**
  4→ * Contract: Declares the encryption mechanism for a field. Each variant maps 1:1 to an encryption
  5→ * family and exposes capability methods that the {@link jlsm.table.internal.IndexRegistry} uses to
  6→ * validate index compatibility at schema construction time.
  7→ *
  8→ * <p>
  9→ * Governed by: .decisions/field-encryption-api-design/adr.md
 10→ */
 11→public sealed interface EncryptionSpec permits EncryptionSpec.None, EncryptionSpec.Deterministic,
 12→        EncryptionSpec.OrderPreserving, EncryptionSpec.DistancePreserving, EncryptionSpec.Opaque {
 13→
 14→    /** The singleton no-encryption specification. */
 15→    EncryptionSpec NONE = new None();
 16→
 17→    // ── Capability query methods ──────────────────────────────────────────────
 18→
 19→    /** Returns {@code true} if equality comparisons are supported on encrypted values. */
 20→    default boolean supportsEquality() {
 21→        return false;
 22→    }
 23→
 24→    /** Returns {@code true} if range (ordering) queries are supported on encrypted values. */
 25→    default boolean supportsRange() {
 26→        return false;
 27→    }
 28→
 29→    /** Returns {@code true} if keyword (single-term) search is supported on encrypted values. */
 30→    default boolean supportsKeywordSearch() {
 31→        return false;
 32→    }
 33→
 34→    /** Returns {@code true} if phrase / proximity search is supported on encrypted values. */
 35→    default boolean supportsPhraseSearch() {
 36→        return false;
 37→    }
 38→
 39→    /** Returns {@code true} if SSE-based encrypted index search is supported. */
 40→    default boolean supportsSseSearch() {
 41→        return false;
 42→    }
 43→
 44→    /**
 45→     * Returns {@code true} if approximate nearest-neighbor search is supported on encrypted values.
 46→     */
 47→    default boolean supportsANN() {
 48→        return false;
 49→    }
 50→
 51→    // ── Permits ───────────────────────────────────────────────────────────────
 52→
 53→    /**
 54→     * No encryption — field values are stored in plaintext. All capabilities are trivially
 55→     * supported (delegated to the underlying index).
 56→     */
 57→    record None() implements EncryptionSpec {
 58→        @Override
 59→        public boolean supportsEquality() {
 60→            return true;
 61→        }
 62→
 63→        @Override
 64→        public boolean supportsRange() {
 65→            return true;
 66→        }
 67→
 68→        @Override
 69→        public boolean supportsKeywordSearch() {
 70→            return true;
 71→        }
 72→
 73→        @Override
 74→        public boolean supportsPhraseSearch() {
 75→            return true;
 76→        }
 77→
 78→        @Override
 79→        public boolean supportsSseSearch() {
 80→            return true;
 81→        }
 82→
 83→        @Override
 84→        public boolean supportsANN() {
 85→            return true;
 86→        }
 87→    }
 88→
 89→    /**
 90→     * Deterministic encryption (AES-SIV). Same plaintext always produces the same ciphertext under
 91→     * the same key, enabling equality comparisons and keyword search via inverted index.
 92→     */
 93→    record Deterministic() implements EncryptionSpec {
 94→        @Override
 95→        public boolean supportsEquality() {
 96→            return true;
 97→        }
 98→
 99→        @Override
100→        public boolean supportsKeywordSearch() {
101→            return true;
102→        }
103→    }
104→
105→    /**
106→     * Order-preserving encryption (Boldyreva OPE). Ciphertext ordering matches plaintext ordering,
107→     * enabling range queries. Also supports equality.
108→     */
109→    record OrderPreserving() implements EncryptionSpec {
110→        @Override
111→        public boolean supportsEquality() {
112→            return true;
113→        }
114→
115→        @Override
116→        public boolean supportsRange() {
117→            return true;
118→        }
119→    }
120→
121→    /**
122→     * Distance-comparison-preserving encryption (DCPE / Scale-And-Perturb). Encrypted vectors
123→     * approximate the distance relationships of plaintext vectors, enabling ANN search.
124→     */
125→    record DistancePreserving() implements EncryptionSpec {
126→        @Override
127→        public boolean supportsANN() {
128→            return true;
129→        }
130→    }
131→
132→    /**
133→     * Opaque encryption (AES-GCM). No search capability — values must be decrypted before any
134→     * comparison. Provides the strongest security guarantee.
135→     */
136→    record Opaque() implements EncryptionSpec {
137→        // All capabilities default to false
138→    }
139→
140→    // ── Static factory methods ────────────────────────────────────────────────
141→
142→    /** Returns the no-encryption specification. */
143→    static EncryptionSpec none() {
144→        return NONE;
145→    }
146→
147→    /** Returns a deterministic encryption specification (AES-SIV). */
148→    static EncryptionSpec deterministic() {
149→        return new Deterministic();
150→    }
151→
152→    /** Returns an order-preserving encryption specification (Boldyreva OPE). */
153→    static EncryptionSpec orderPreserving() {
154→        return new OrderPreserving();
155→    }
156→
157→    /** Returns a distance-preserving encryption specification (DCPE / SAP). */
158→    static EncryptionSpec distancePreserving() {
159→        return new DistancePreserving();
160→    }
161→
162→    /** Returns an opaque encryption specification (AES-GCM). */
163→    static EncryptionSpec opaque() {
164→        return new Opaque();
165→    }
166→}
