  1→package jlsm.table;
  2→
  3→import java.util.ArrayList;
  4→import java.util.HashMap;
  5→import java.util.List;
  6→import java.util.Map;
  7→import java.util.Objects;
  8→import java.util.function.Consumer;
  9→
 10→/**
 11→ * Describes the structure of documents stored in a {@link JlsmTable}.
 12→ *
 13→ * <p>
 14→ * A schema has a name, a version, an ordered list of {@link FieldDefinition}s, and a maximum
 15→ * nesting depth limit for object fields.
 16→ */
 17→public final class JlsmSchema {
 18→
 19→    private static final int DEFAULT_MAX_DEPTH = 10;
 20→    private static final int ABSOLUTE_MAX_DEPTH = 25;
 21→
 22→    private final String name;
 23→    private final int version;
 24→    private final List<FieldDefinition> fields;
 25→    private final int maxDepth;
 26→    private final Map<String, Integer> fieldIndexMap;
 27→
 28→    private JlsmSchema(String name, int version, List<FieldDefinition> fields, int maxDepth) {
 29→        assert name != null : "name must not be null";
 30→        assert fields != null : "fields must not be null";
 31→        assert maxDepth >= 0 && maxDepth <= ABSOLUTE_MAX_DEPTH : "maxDepth out of range";
 32→
 33→        this.name = name;
 34→        this.version = version;
 35→        this.fields = List.copyOf(fields);
 36→        this.maxDepth = maxDepth;
 37→
 38→        // Build field index map for O(1) lookup
 39→        final Map<String, Integer> indexMap = new HashMap<>(fields.size() * 2);
 40→        for (int i = 0; i < fields.size(); i++) {
 41→            indexMap.put(fields.get(i).name(), i);
 42→        }
 43→        this.fieldIndexMap = Map.copyOf(indexMap);
 44→    }
 45→
 46→    /** Returns the schema name. */
 47→    public String name() {
 48→        return name;
 49→    }
 50→
 51→    /** Returns the schema version. */
 52→    public int version() {
 53→        return version;
 54→    }
 55→
 56→    /** Returns an unmodifiable ordered list of field definitions. */
 57→    public List<FieldDefinition> fields() {
 58→        return fields;
 59→    }
 60→
 61→    /** Returns the maximum allowed nesting depth for object fields. */
 62→    public int maxDepth() {
 63→        return maxDepth;
 64→    }
 65→
 66→    /**
 67→     * Returns the zero-based index of the field with the given name, or {@code -1} if no such field
 68→     * exists.
 69→     *
 70→     * @param name the field name to look up; must not be null
 71→     * @return the field index, or -1 if not found
 72→     */
 73→    public int fieldIndex(String name) {
 74→        Objects.requireNonNull(name, "name must not be null");
 75→        return fieldIndexMap.getOrDefault(name, -1);
 76→    }
 77→
 78→    /**
 79→     * Creates a new {@link Builder} for a schema with the given name and version.
 80→     *
 81→     * @param name the schema name; must not be null
 82→     * @param version the schema version
 83→     * @return a new Builder
 84→     */
 85→    public static Builder builder(String name, int version) {
 86→        Objects.requireNonNull(name, "name must not be null");
 87→        return new Builder(name, version, 0, DEFAULT_MAX_DEPTH, null);
 88→    }
 89→
 90→    /**
 91→     * Builder for {@link JlsmSchema}.
 92→     *
 93→     * <p>
 94→     * The builder tracks a current nesting depth; {@link #objectField} creates a nested builder at
 95→     * {@code depth + 1}. {@link #build()} validates that no level exceeds the configured
 96→     * {@code maxDepth}.
 97→     */
 98→    public static final class Builder {
 99→
100→        private final String name;
101→        private final int version;
102→        private final int currentDepth;
103→        private final List<FieldDefinition> fields = new ArrayList<>();
104→
105→        // maxDepth is tracked on the root builder; nested builders reference the root
106→        private int maxDepth;
107→        // parentBuilder is null for the root; non-null for nested builders
108→        private final Builder rootBuilder;
109→
110→        private Builder(String name, int version, int currentDepth, int maxDepth,
111→                Builder rootBuilder) {
112→            this.name = name;
113→            this.version = version;
114→            this.currentDepth = currentDepth;
115→            this.maxDepth = maxDepth;
116→            this.rootBuilder = rootBuilder;
117→        }
118→
119→        /**
120→         * Adds a primitive or array field to this schema level.
121→         *
122→         * @param name the field name; must not be null
123→         * @param type the field type; must not be null
124→         * @return this builder
125→         */
126→        public Builder field(String name, FieldType type) {
127→            Objects.requireNonNull(name, "name must not be null");
128→            Objects.requireNonNull(type, "type must not be null");
129→            assert name != null : "name must not be null";
130→            assert type != null : "type must not be null";
131→            fields.add(new FieldDefinition(name, type));
132→            return this;
133→        }
134→
135→        /**
136→         * Adds a primitive or array field with an explicit encryption specification.
137→         *
138→         * @param name the field name; must not be null
139→         * @param type the field type; must not be null
140→         * @param encryption the encryption spec; must not be null
141→         * @return this builder
142→         */
143→        public Builder field(String name, FieldType type, EncryptionSpec encryption) {
144→            Objects.requireNonNull(name, "name must not be null");
145→            Objects.requireNonNull(type, "type must not be null");
146→            Objects.requireNonNull(encryption, "encryption must not be null");
147→            assert name != null : "name must not be null";
148→            assert type != null : "type must not be null";
149→            assert encryption != null : "encryption must not be null";
150→            fields.add(new FieldDefinition(name, type, encryption));
151→            return this;
152→        }
153→
154→        /**
155→         * Adds a vector field with the given element type and fixed dimensions.
156→         *
157→         * @param name the field name; must not be null
158→         * @param elementType the element precision; must be FLOAT16 or FLOAT32
159→         * @param dimensions the fixed number of elements per vector; must be positive
160→         * @return this builder
161→         */
162→        public Builder vectorField(String name, FieldType.Primitive elementType, int dimensions) {
163→            Objects.requireNonNull(name, "name must not be null");
164→            Objects.requireNonNull(elementType, "elementType must not be null");
165→            assert name != null : "name must not be null";
166→            assert elementType != null : "elementType must not be null";
167→            return field(name, FieldType.vector(elementType, dimensions));
168→        }
169→
170→        /**
171→         * Adds a nested object field by building its inner schema inline via a Consumer.
172→         *
173→         * <p>
174→         * The nested builder is passed to the consumer at {@code currentDepth + 1}. If the nested
175→         * depth exceeds maxDepth, {@link #build()} will throw.
176→         *
177→         * @param name the field name; must not be null
178→         * @param nested a consumer that populates the nested schema's builder; must not be null
179→         * @return this builder
180→         */
181→        public Builder objectField(String name, Consumer<Builder> nested) {
182→            Objects.requireNonNull(name, "name must not be null");
183→            Objects.requireNonNull(nested, "nested must not be null");
184→            assert name != null : "name must not be null";
185→            assert nested != null : "nested consumer must not be null";
186→
187→            final int nestedDepth = currentDepth + 1;
188→            final Builder root = (rootBuilder != null) ? rootBuilder : this;
189→            final Builder nestedBuilder = new Builder(name, version, nestedDepth, maxDepth, root);
190→            nested.accept(nestedBuilder);
191→
192→            // Build the nested ObjectType — validation happens here
193→            final List<FieldDefinition> nestedFields = nestedBuilder.buildFields(root.maxDepth);
194→            fields.add(new FieldDefinition(name, new FieldType.ObjectType(nestedFields)));
195→            return this;
196→        }
197→
198→        /**
199→         * Sets the maximum nesting depth allowed for object fields. Must be between 0 and 25
200→         * (inclusive).
201→         *
202→         * @param maxDepth the maximum depth
203→         * @return this builder
204→         * @throws IllegalArgumentException if {@code maxDepth} exceeds 25
205→         */
206→        public Builder maxDepth(int maxDepth) {
207→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
208→                throw new IllegalArgumentException("maxDepth " + maxDepth
209→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
210→            }
211→            if (maxDepth < 0) {
212→                throw new IllegalArgumentException("maxDepth must not be negative");
213→            }
214→            this.maxDepth = maxDepth;
215→            return this;
216→        }
217→
218→        /**
219→         * Builds and returns the {@link JlsmSchema}.
220→         *
221→         * @return the constructed schema
222→         * @throws IllegalArgumentException if maxDepth exceeds 25 or if any field's nesting exceeds
223→         *             maxDepth
224→         */
225→        public JlsmSchema build() {
226→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
227→                throw new IllegalArgumentException("maxDepth " + maxDepth
228→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
229→            }
230→            // Depth validation is already done eagerly in objectField → buildFields
231→            return new JlsmSchema(name, version, fields, maxDepth);
232→        }
233→
234→        /**
235→         * Internal helper: returns the fields accumulated by this builder, after validating that
236→         * {@code currentDepth <= allowedMaxDepth}.
237→         *
238→         * @param allowedMaxDepth the depth limit from the root builder
239→         * @return the list of field definitions
240→         * @throws IllegalArgumentException if this builder's depth exceeds allowedMaxDepth
241→         */
242→        private List<FieldDefinition> buildFields(int allowedMaxDepth) {
243→            if (currentDepth > allowedMaxDepth) {
244→                throw new IllegalArgumentException("Nested object depth " + currentDepth
245→                        + " exceeds maxDepth " + allowedMaxDepth);
246→            }
247→            return List.copyOf(fields);
248→        }
249→    }
250→}
