115→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
116→
117→        private final JlsmSchema schema;
118→        private final boolean[] isBoolField;
119→        private final int[] prefixBoolCount;
120→        private final int fieldCount;
121→        private final int boolCount;
122→        private final int nullMaskBytes;
123→        private final int boolMaskBytes;
124→        private final FieldDecoder[] decoders;
125→
126→        SchemaSerializer(JlsmSchema schema) {
127→            this.schema = schema;
128→
129→            final List<FieldDefinition> fields = schema.fields();
130→            this.fieldCount = fields.size();
131→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
132→
133→            // Precompute boolean field flags and prefix counts
134→            this.isBoolField = new boolean[fieldCount];
135→            this.prefixBoolCount = new int[fieldCount + 1];
136→            int bools = 0;
137→            for (int i = 0; i < fieldCount; i++) {
138→                prefixBoolCount[i] = bools;
139→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
140→                    isBoolField[i] = true;
141→                    bools++;
142→                }
143→            }
144→            prefixBoolCount[fieldCount] = bools;
145→            this.boolCount = bools;
146→
147→            this.nullMaskBytes = (fieldCount + 7) / 8;
148→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
149→
150→            // Build dispatch table for non-boolean field decoders
151→            this.decoders = new FieldDecoder[fieldCount];
152→            for (int i = 0; i < fieldCount; i++) {
153→                if (!isBoolField[i]) {
154→                    final FieldType type = fieldArray[i].type();
155→                    decoders[i] = (buf, cursor) -> decodeField(buf, cursor, type);
156→                }
157→            }
158→        }
159→
160→        @Override
161→        public MemorySegment serialize(JlsmDocument doc) {
162→            Objects.requireNonNull(doc, "doc must not be null");
163→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
164→                    : "document schema mismatch";
165→
166→            final List<FieldDefinition> fields = schema.fields();
167→            final int fieldCount = fields.size();
168→            final Object[] values = doc.values();
169→
170→            // Count boolean fields
171→            final int boolCount = countBoolFields(fields);
172→
173→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
174→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
175→            final int nullMaskBytes = (fieldCount + 7) / 8;
176→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
177→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
178→
179→            // Two-pass: measure then encode
180→            final int payloadSize = measureFields(fields, values);
181→            final int totalSize = headerSize + payloadSize;
182→
183→            final byte[] buf = new byte[totalSize];
184→
185→            // Write header
186→            writeShortBE(buf, 0, (short) schema.version());
187→            writeShortBE(buf, 2, (short) fieldCount);
188→            // Null bitmask
189→            buildNullMask(fields, values, buf, 4);
190→            // Boolean bitmask
191→            if (boolCount > 0) {
192→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
193→            }
194→
195→            // Write values
196→            final Cursor cursor = new Cursor(buf, headerSize);
197→            encodeFields(fields, values, cursor);
198→
199→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
200→            return MemorySegment.ofArray(buf);
201→        }
202→
203→        @Override
204→        public JlsmDocument deserialize(MemorySegment segment) {
205→            Objects.requireNonNull(segment, "segment must not be null");
206→
207→            final ByteArrayView view = extractBytes(segment);
208→            final byte[] buf = view.data();
209→            final Cursor cursor = new Cursor(buf, view.offset());
210→
211→            // Read header
212→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
213→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
214→
215→            // We only read min(writeFieldCount, currentFieldCount) fields
216→            final int readCount = Math.min(writeFieldCount, fieldCount);
217→
218→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
219→            final int writeBoolCount = prefixBoolCount[readCount];
220→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
221→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
222→
223→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
224→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
225→
226→            // Decode values
227→            final Object[] values = new Object[fieldCount];
228→            // Fields beyond readCount remain null (new fields added in a later schema version)
229→
230→            int boolIdx = 0;
231→            for (int i = 0; i < readCount; i++) {
232→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
233→                if (isNull) {
234→                    if (isBoolField[i]) {
235→                        boolIdx++;
236→                    }
237→                    continue;
238→                }
239→                if (isBoolField[i]) {
240→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
241→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
242→                    boolIdx++;
243→                } else {
244→                    values[i] = decoders[i].decode(buf, cursor);
245→                }
246→            }
247→
248→            return new JlsmDocument(schema, values);
249→        }
250→    }
